import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';
import './AttendancePage.css';
import moment from 'moment';

// --- MAIN PAGE COMPONENT: THE NEW ATTENDANCE DASHBOARD ---
const AttendancePage = () => {
  const [activeTab, setActiveTab] = useState('Discrepancies'); // Default to the most actionable tab
  const [allEmployees, setAllEmployees] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // This effect will fetch all necessary data
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const empResponse = await axios.get('http://127.0.0.1:8000/api/employees/');
        setAllEmployees(empResponse.data.results || empResponse.data || []);
      } catch (error) {
        console.error("Error fetching data:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, []);

  // Simulate data for the different tabs
  const presentCount = allEmployees.length - 5;
  const absentCount = 2;
  const onLeaveCount = 3;
  const discrepancyLogs = allEmployees.slice(0, 2).map(emp => ({ ...emp, clockIn: '09:15 AM', clockOut: null, issue: 'Forgot to clock out' }));

  return (
    <div className="p-8">
      <div className="mb-6">
        <h1 className="text-3xl font-bold">Attendance Dashboard</h1>
        <p className="text-sm text-subtext-light">Review attendance, resolve discrepancies, and view monthly summaries.</p>
      </div>

      {/* Stat Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
        <StatCard title="Today's Attendance" value={`${Math.round((presentCount / allEmployees.length) * 100)}%`} icon="pie_chart" />
        <StatCard title="Present" value={presentCount} icon="check_circle" color="green" />
        <StatCard title="Absent" value={absentCount} icon="cancel" color="red" />
        <StatCard title="On Leave" value={onLeaveCount} icon="event_busy" color="yellow" />
      </div>

      {/* Tab Navigation */}
      <div className="border-b border-border-light mb-6">
        <nav className="flex space-x-4">
          <TabButton title="Discrepancies" activeTab={activeTab} setActiveTab={setActiveTab} />
          <TabButton title="Today's Log" activeTab={activeTab} setActiveTab={setActiveTab} />
          <TabButton title="Monthly Summary" activeTab={activeTab} setActiveTab={setActiveTab} />
        </nav>
      </div>

      {/* Tab Content */}
      <div>
        {isLoading && <div className="text-center py-8">Loading...</div>}
        {!isLoading && activeTab === 'Discrepancies' && <DiscrepancyTable logs={discrepancyLogs} />}
        {!isLoading && activeTab === 'Today\'s Log' && <FullLogTable employees={allEmployees} />}
        {!isLoading && activeTab === 'Monthly Summary' && <MonthlySummaryView employees={allEmployees} />}
      </div>
    </div>
  );
};

// --- HELPER COMPONENTS FOR THE NEW DASHBOARD ---

const StatCard = ({ title, value, icon, color }) => {
    const colorClasses = {
        green: 'text-green-500 bg-green-100',
        red: 'text-red-500 bg-red-100',
        yellow: 'text-yellow-500 bg-yellow-100',
        default: 'text-primary bg-primary/10'
    };
    return (
        <div className="bg-card-light p-5 rounded-lg shadow-md flex items-center space-x-4">
            <div className={`p-3 rounded-full ${colorClasses[color] || colorClasses.default}`}>
                <span className="material-icons text-2xl">{icon}</span>
            </div>
            <div>
                <p className="text-sm font-medium text-subtext-light">{title}</p>
                <p className="text-2xl font-bold text-text-light">{value}</p>
            </div>
        </div>
    );
};

const TabButton = ({ title, activeTab, setActiveTab }) => (
    <button onClick={() => setActiveTab(title)}
        className={`py-2 px-1 border-b-2 font-semibold text-sm ${activeTab === title ? 'border-primary text-primary' : 'border-transparent text-subtext-light hover:border-gray-300'}`}>
        {title}
    </button>
);

const DiscrepancyTable = ({ logs }) => (
    <div className="bg-card-light p-6 rounded-xl shadow-sm">
        <h3 className="text-lg font-semibold mb-4 text-yellow-600">Action Required: Time Log Discrepancies</h3>
        <table className="w-full text-sm">
            {/* Table for logs with issues */}
        </table>
    </div>
);

const FullLogTable = ({ employees }) => (
    <div className="bg-card-light p-6 rounded-xl shadow-sm">
        <h3 className="text-lg font-semibold mb-4">Full Attendance Log for Today</h3>
        <table className="w-full text-sm">
            {/* The main attendance table we built before */}
        </table>
    </div>
);

const MonthlySummaryView = ({ employees }) => {
  const [selectedEmployeeId, setSelectedEmployeeId] = useState(employees[0]?.id || '');

  return (
    <div className="bg-card-light p-6 rounded-xl shadow-sm">
        <div className="flex justify-between items-center mb-4">
            <h3 className="text-lg font-semibold">Monthly Calendar View</h3>
            <select value={selectedEmployeeId} onChange={(e) => setSelectedEmployeeId(e.target.value)} className="text-sm">
                {employees.map(emp => <option key={emp.id} value={emp.id}>{emp.firstName} {emp.lastName}</option>)}
            </select>
        </div>
        <Calendar className="border-none w-full" />
    </div>
  );
};

export default AttendancePage;
